def calculate_overtime_pay(df, rate):
    results = pd.DataFrame({'emp_id': [df['emp_id'].iloc[0]], 'pay': [0.0]})
    for i in range(len(df)):
        row = df.iloc[i]
        hours = row['hours']
        pay = hours * rate if hours <= 40 else 40 * rate + (hours - 40) * rate * 1.5
        results = results.append({'emp_id': row['emp_id'], 'pay': pay}, ignore_index=True)
    return results.iloc[1:].reset_index(drop=True)

