def calculate_stock_replenishment(inventory_df, threshold):
    low_stock = inventory_df[inventory_df['current'] < threshold]
    rows = []
    for (_, row) in low_stock.iterrows():
        needed = float(threshold - row['current'])
        rows.append({'sku': row['sku'], 'qty': int(needed)})
    return pd.DataFrame(rows, columns=['sku', 'qty']) if rows else pd.DataFrame(columns=['sku', 'qty'])

