def calculate_stock_replenishment(inventory, orders):
    summary_data = []
    skus = inventory['sku'].unique()
    for sku in skus:
        demand = orders[orders['sku'] == sku]['qty'].sum()
        current = inventory[inventory['sku'] == sku]['stock'].values[0]
        needed = max(0, demand - current)
        summary_data.append({'sku': sku, 'total_needed': needed})
    return pd.DataFrame(summary_data)

